export const STORAGE_KEY='case-room-v1';
export const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
export const uid=()=>globalThis.crypto?.randomUUID?.()||`case-${Date.now()}-${Math.random().toString(36).slice(2)}`;
export const text=v=>typeof v==='string'?v.slice(0,15000):typeof v==='number'&&Number.isFinite(v)?String(v):'';
export function number(v,min=0,max=1e9){if(typeof v!=='string'&&typeof v!=='number'||String(v).trim()==='')return null;const n=Number(v);return Number.isFinite(n)&&n>=min&&n<=max?n:null;}
export function safeUrl(v){try{const u=new URL(v);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:null;}catch{return null;}}
export function blankCase(){return {id:uid(),sample:false,name:'',team:'',date:today(),decision:'',objective:'',constraints:'',mustAnswer:'',recommendation:'',rationale:'',assumption:'',economics:'',objection:'',response:'',implementation:'',options:Array.from({length:3},(_,i)=>({name:'',description:''})),criteria:[{name:'Impact',weight:'35'},{name:'Feasibility',weight:'25'},{name:'Economics',weight:'25'},{name:'Speed to results',weight:'15'}],scores:Array.from({length:3},()=>Array(4).fill('')),claims:Array.from({length:3},()=>({claim:'',source:'',url:'',date:'',locator:''})),pitchMinutes:'5',slides:Array.from({length:6},(_,i)=>({headline:['The recommendation','The problem worth solving','The alternatives','The case for our choice','The execution plan','The risk and the ask'][i],points:'',seconds:String([30,45,60,75,60,30][i]),essential:i!==2})),storyFingerprint:'',answers:{},lastRehearsal:null,updatedAt:new Date().toISOString()};}
export function sampleCase(){const b=blankCase();Object.assign(b,{sample:true,name:'CampusBite: the next growth move',team:'Team North Star',decision:'Which growth channel should CampusBite prioritise for its next six-month pilot?',objective:'Reach 600 recurring student subscribers while keeping acquisition payback below three months.',constraints:'Pilot budget: ₹6 lakh. Two-person operations team. Six-month decision window.',mustAnswer:'Choose one growth channel.\nExplain unit economics and key assumptions.\nShow a six-month rollout and measurable milestones.',recommendation:'1',rationale:'Pilot campus ambassadors on two campuses. This combines peer-led distribution with a smaller operational commitment than opening kiosks. Gate expansion on repeat purchase and acquisition payback.',assumption:'Student referrals can acquire paying subscribers for ₹300 or less, with at least 60% retained after month two.',economics:'Illustrative assumptions: ₹300 acquisition cost; ₹150 monthly contribution per subscriber before fixed overhead. Simple contribution payback = 2 months. Test retention and capacity before extrapolating.',objection:'Ambassadors may drive discount-led sign-ups that do not retain.',response:'Link ambassador rewards to second-month renewal. Run a small cohort and compare retention against direct subscribers before expanding.',implementation:'Weeks 1–2 · Growth lead: recruit 6 ambassadors across 2 campuses. KPI: 100 qualified trial sign-ups.\nWeeks 3–8 · Ops lead: run paid cohorts. KPI: acquisition cost ≤ ₹300 and month-two retention ≥ 60%.\nMonths 3–6 · Team lead: scale only after both gates pass. KPI: 600 active subscribers within the pilot budget.',options:[{name:'Campus kiosks',description:'Open two small on-campus sales points.'},{name:'Student ambassadors',description:'Recruit peer representatives and reward retained subscriptions.'},{name:'Paid social',description:'Run targeted digital acquisition campaigns.'}],scores:[['4','2','2','2'],['4','4','4','4'],['3','4','2','5']],claims:[{claim:'Peer referrals may make student acquisition more efficient.',source:'Assumption — validate with a campus pilot',url:'',date:'',locator:''},{claim:'Retention determines whether the channel economics hold.',source:'Illustrative model — replace with cohort evidence',url:'',date:'',locator:''},{claim:'Kiosks require more operating capacity than the team has today.',source:'Assumption — validate staffing and campus permissions',url:'',date:'',locator:''}]});b.slides=generateStory(b);b.storyFingerprint=decisionFingerprint(b);return b;}
export function matrix(b){const errors=[],weights=b.criteria.map(c=>number(c.weight,0,100));if(weights.some(w=>w===null))errors.push('Enter weights between 0 and 100.');const total=weights.reduce((s,w)=>s+(w??0),0);if(Math.abs(total-100)>.001)errors.push(`Weights total ${Number(total.toFixed(2))}%. They must total 100%.`);if(b.criteria.some(c=>!c.name.trim()))errors.push('Name every decision criterion.');if(b.options.some(o=>!o.name.trim()))errors.push('Name all three alternatives.');const scores=b.scores.map(row=>row.map(s=>number(s,1,5)));if(scores.some(row=>row.some(s=>s===null)))errors.push('Score every option from 1 to 5. Missing scores are not zero.');const valid=!errors.length;const totals=valid?scores.map(row=>row.reduce((s,x,j)=>s+x*weights[j]/100,0)):[null,null,null];const max=valid?Math.max(...totals):null;const leaders=valid?totals.flatMap((v,i)=>Math.abs(v-max)<1e-8?[i]:[]):[];return {valid,errors,total,weights,scores,totals,leaders};}
export function sensitivity(b){const m=matrix(b);if(!m.valid)return [];return b.criteria.map((c,k)=>{const old=m.weights[k],newWeight=Math.min(100,old+10);if(old>=100||newWeight===old)return null;const w=m.weights.map((v,j)=>j===k?newWeight:v*(100-newWeight)/(100-old));const totals=m.scores.map(row=>row.reduce((s,x,j)=>s+x*w[j]/100,0));const max=Math.max(...totals),leaders=totals.flatMap((x,i)=>Math.abs(x-max)<1e-8?[i]:[]);return {criterion:c.name,weight:newWeight,leaders,changed:leaders.join(',')!==m.leaders.join(',')};}).filter(Boolean);}
export function chosen(b){const i=number(b.recommendation,0,2);return i!==null&&Number.isInteger(i)?i:null;}
// A bounded change detector keeps derived context out of the backup's text limits.
// This is deliberately not a security or authenticity hash.
function fingerprint(value){const s=JSON.stringify(value);let a=2166136261,b=2246822519;for(let i=0;i<s.length;i++){const c=s.charCodeAt(i);a=Math.imul(a^c,16777619);b=Math.imul(b^c,3266489917);}return `v2:${s.length}:${(a>>>0).toString(16)}:${(b>>>0).toString(16)}`;}
export function decisionFingerprint(b){return fingerprint([b.name,b.decision,b.objective,b.constraints,b.mustAnswer,b.recommendation,b.rationale,b.economics,b.objection,b.response,b.implementation,b.options,b.criteria,b.scores,b.claims]);}
export function generateStory(b){const c=chosen(b),choice=c===null?'[Choose your recommendation]':b.options[c].name||'[Name the chosen option]',m=matrix(b);return [
{headline:`Prioritise ${choice}`,points:b.rationale||'[State the recommendation and the main reason.]',seconds:'30',essential:true},
{headline:b.objective||'[State the goal and why it matters]',points:`Decision: ${b.decision||'[Define the decision.]'}\nConstraints: ${b.constraints||'[Name the binding constraints.]'}`,seconds:'45',essential:true},
{headline:'Why this option beats the alternatives',points:b.options.map((o,i)=>`${o.name||'[Name option]'}: ${o.description||'[Explain the trade-off.]'}${m.valid?` · team score ${m.totals[i].toFixed(2)}/5`:''}`).join('\n'),seconds:'60',essential:false},
{headline:'The evidence and economics behind the choice',points:`${b.claims.filter(c=>c.claim.trim()).map(c=>c.claim).join('\n')||'[Add the supporting evidence.]'}\nEconomics: ${b.economics||'[Show the economics and label assumptions.]'}`,seconds:'75',essential:true},
{headline:'A staged rollout with measurable gates',points:b.implementation||'[List first actions, accountable owners, and success metrics.]',seconds:'60',essential:true},
{headline:'Protect the downside before scaling',points:`Objection: ${b.objection||'[Name the strongest objection.]'}\nResponse: ${b.response||'[Explain the mitigation.]'}\nAsk: ${b.mustAnswer||'[State what the judges should approve or remember.]'}`,seconds:'30',essential:true}
];}
export function allocateSlides(slides,minutes){const target=number(minutes,.5,120);if(target===null)return slides;const total=Math.round(target*60),weights=[.1,.15,.2,.25,.2,.1];let assigned=0;return slides.map((s,i)=>{const sec=i===5?total-assigned:Math.floor(total*weights[i]);assigned+=sec;return {...s,seconds:String(sec)};});}
export function plan(b){const minutes=number(b.pitchMinutes,.5,120),seconds=b.slides.map(s=>number(s.seconds,1,7200)),total=seconds.reduce((s,v)=>s+(v??0),0),target=minutes===null?null:Math.round(minutes*60),errors=[];if(minutes===null)errors.push('Pitch target must be between 0.5 and 120 minutes.');if(seconds.some(s=>s===null))errors.push('Give every slide a positive duration in seconds.');if(target!==null&&Math.abs(target-total)>.01)errors.push(`Slide allocations total ${total}s; target is ${target}s. Fit the timings or edit them to match.`);if(b.slides.some(s=>!s.headline.trim()))errors.push('Give every slide a headline.');return {valid:!errors.length,errors,total,target,seconds};}
export function questions(b){const c=chosen(b),m=matrix(b),choice=c===null?'your recommendation':b.options[c].name||'your recommendation';const rivals=b.options.map((o,i)=>({i,name:o.name,score:m.totals[i]??0})).filter(o=>o.i!==c&&o.name).sort((a,b)=>b.score-a.score);const rival=rivals[0]?.name||'the strongest rejected alternative';const recommendation=[b.recommendation,c===null?null:b.options[c],b.rationale],facts={rival:[b.options,b.criteria,b.scores,b.objective,b.constraints],assumption:[b.assumption,b.objection,b.response,b.economics],economics:[b.economics,b.assumption,b.claims],execution:[b.implementation,b.objective,b.constraints],evidence:[b.claims],brief:[b.mustAnswer,b.constraints,b.implementation]};return [
{id:'rival',label:'The trade-off',question:`Why choose ${choice} over ${rival}? What would have to change for the alternative to win?`,hint:m.valid?`Your team scores: ${b.options.map((o,i)=>o.name+' '+m.totals[i].toFixed(2)).join(' · ')}. Scores are judgments, not proof.`:'Your comparison matrix is incomplete. Explain the trade-off without relying on a ranking.'},
{id:'assumption',label:'The weak link',question:b.assumption.trim()?`What happens if this assumption is wrong: “${b.assumption}”?`:'Which single assumption is most likely to break your recommendation?',hint:'Describe a validation test, a threshold, and the fallback decision.'},
{id:'economics',label:'The numbers',question:'Walk us through the economics. Which inputs are observed, which are assumptions, and what happens in the downside case?',hint:b.economics||'Your economics section is blank. Do not invent numbers to fill it.'},
{id:'execution',label:'The first move',question:`Who owns the first action, and how will you know it is working${b.objective.trim()?` toward “${b.objective}”`:''}?`,hint:b.implementation||'No implementation steps yet. Name an owner, timeline, and KPI.'},
{id:'evidence',label:'The evidence',question:'Which piece of evidence most strongly supports your recommendation, and how could we verify it?',hint:`${b.claims.filter(x=>x.claim.trim()&&x.source.trim()&&safeUrl(x.url)&&x.date).length}/3 claims have a source title, valid link, and date. Uncited statements remain assumptions.`},
{id:'brief',label:'The competition brief',question:'How does your recommendation satisfy the required deliverables and binding constraints?',hint:[b.mustAnswer,b.constraints].filter(Boolean).join('\n')||'Add the must-answer requirements from the official competition brief.'}
].map(q=>({...q,context:fingerprint([recommendation,facts[q.id]])}));}
export const questionContext=q=>fingerprint([q.question,q.hint,q.context]);
export const prepareAnswer=(q,value)=>({text:value,ready:!!value.trim(),context:questionContext(q)});
export const answerPrepared=(b,q)=>!!b.answers[q.id]?.ready&&!!b.answers[q.id]?.text?.trim()&&b.answers[q.id]?.context===questionContext(q);
export function syncAnswers(b){for(const q of questions(b)){const a=b.answers[q.id];if(a?.ready&&!answerPrepared(b,q))a.ready=false;}}
export function readiness(b){const m=matrix(b);return [{label:'Decision, goal, and constraints',done:!!b.decision.trim()&&!!b.objective.trim()&&!!b.constraints.trim()},{label:'Official must-answer requirements',done:!!b.mustAnswer.trim()},{label:'Three options compared with valid weights',done:m.valid},{label:'Recommendation and rationale',done:chosen(b)!==null&&!!b.rationale.trim()},{label:'Evidence with source details',done:b.claims.every(c=>c.claim.trim()&&c.source.trim()&&safeUrl(c.url)&&c.date)},{label:'Critical assumption and response to objections',done:!!b.assumption.trim()&&!!b.objection.trim()&&!!b.response.trim()},{label:'Economics and implementation',done:!!b.economics.trim()&&!!b.implementation.trim()},{label:'Six slide headlines with speaking points',done:b.slides.every(s=>s.headline.trim()&&s.points.trim())},{label:'Pitch allocations match the target',done:plan(b).valid},{label:'All six judge answers marked prepared',done:questions(b).every(q=>answerPrepared(b,q))}];}
export const newTimer=()=>({running:false,elapsedMs:0,startedAt:null,slide:0,slideStartMs:0,splits:[],finished:false});
export const elapsed=(t,now)=>t.elapsedMs+(t.running?Math.max(0,now-t.startedAt):0);
export function start(t,now){return t.running||t.finished?t:{...t,running:true,startedAt:now};}
export function pause(t,now){return {...t,elapsedMs:elapsed(t,now),running:false,startedAt:null};}
export function advance(t,now){if(t.finished)return t;const e=elapsed(t,now),splits=[...t.splits,{slide:t.slide,seconds:(e-t.slideStartMs)/1000}];return t.slide>=5?{...pause(t,now),splits,finished:true}:{...t,slide:t.slide+1,slideStartMs:e,splits};}
export const clock=s=>{const n=Math.ceil(Math.abs(s));return `${s<0?'−':''}${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;};
export function pacing(b,t,now){const p=plan(b),e=elapsed(t,now)/1000,current=e-t.slideStartMs/1000,plannedBefore=p.seconds.slice(0,t.slide).reduce((s,v)=>s+(v||0),0),behind=Math.max(0,t.slideStartMs/1000-plannedBefore+Math.max(0,current-(p.seconds[t.slide]||0))),optional=b.slides.findIndex((s,i)=>i>t.slide&&!s.essential);return {elapsed:e,current,remaining:(p.target??0)-e,slideRemaining:(p.seconds[t.slide]??0)-current,behind,optional};}
export function normalizeCase(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw)||typeof raw.name!=='string'||!Array.isArray(raw.options)||raw.options.length!==3||!Array.isArray(raw.criteria)||raw.criteria.length!==4||!Array.isArray(raw.scores)||raw.scores.length!==3||raw.scores.some(row=>!Array.isArray(row)||row.length!==4)||!Array.isArray(raw.slides)||raw.slides.length!==6||(!Array.isArray(raw.claims)||raw.claims.length!==3))throw new Error('Choose a Case Room JSON backup with three options and six slides.');const b=blankCase();for(const k of ['name','team','date','decision','objective','constraints','mustAnswer','recommendation','rationale','assumption','economics','objection','response','implementation','pitchMinutes','storyFingerprint'])b[k]=text(raw[k]);b.id=typeof raw.id==='string'&&raw.id.length<100?raw.id:uid();b.sample=raw.sample===true;b.updatedAt=typeof raw.updatedAt==='string'&&!isNaN(Date.parse(raw.updatedAt))?raw.updatedAt:new Date().toISOString();b.options=raw.options.map(o=>({name:text(o?.name),description:text(o?.description)}));b.criteria=raw.criteria.map(c=>({name:text(c?.name),weight:text(c?.weight)}));b.scores=raw.scores.map(row=>Array.from({length:4},(_,i)=>text(row?.[i])));b.slides=raw.slides.map(s=>({headline:text(s?.headline),points:text(s?.points),seconds:text(s?.seconds),essential:s?.essential!==false}));b.claims=Array.from({length:3},(_,i)=>Object.fromEntries(['claim','source','url','date','locator'].map(k=>[k,text(raw.claims[i]?.[k])])));b.answers=Object.fromEntries(questions(b).map(q=>[q.id,{text:text(raw.answers?.[q.id]?.text),ready:raw.answers?.[q.id]?.ready===true,context:text(raw.answers?.[q.id]?.context)}]));if(raw.lastRehearsal&&Array.isArray(raw.lastRehearsal.splits)&&raw.lastRehearsal.splits.length===6&&number(raw.lastRehearsal.seconds,0,1e7)!==null)b.lastRehearsal={seconds:Number(raw.lastRehearsal.seconds),splits:raw.lastRehearsal.splits.map((s,i)=>({slide:i,seconds:number(s?.seconds,0,1e7)??0}))};syncAnswers(b);return b;}
export function parseBackup(s){if(s.length>1000000)throw new Error('Choose a backup under 1 MB.');const r=JSON.parse(s);if(r.app!=='case-room'||r.version!==1)throw new Error('Unsupported backup. Choose a Case Room version 1 JSON export.');const b=normalizeCase(r.case);b.id=uid();return b;}
export function restoreLibrary(s){const r=JSON.parse(s);if(r.version!==1||!Array.isArray(r.cases)||!r.cases.length||r.cases.length>100)throw new Error('Saved library format is invalid.');const cases=r.cases.map(normalizeCase);if(new Set(cases.map(b=>b.id)).size!==cases.length)throw new Error('Duplicate saved case IDs.');return {version:1,activeId:cases.some(b=>b.id===r.activeId)?r.activeId:cases[0].id,cases};}
export function markdown(b){const m=matrix(b),c=chosen(b),check=readiness(b);return [`# ${b.name||'Untitled case'}\n${b.team||'Team not entered'} · ${b.date}\n${b.sample?'FICTIONAL DEMONSTRATION: all company information and numbers are illustrative.':'Team-entered content. Sources and conclusions are unverified.'}`,'## 1. Decide',`Decision: ${b.decision||'Not entered'}\nGoal: ${b.objective||'Not entered'}\nConstraints: ${b.constraints||'Not entered'}\nMust answer:\n${b.mustAnswer||'Not entered'}`,`Recommendation: ${c===null?'Not selected':b.options[c].name}\nRationale: ${b.rationale||'Not entered'}`,'### Alternatives and decision matrix',...b.options.map((o,i)=>`${o.name||'Unnamed'}: ${o.description||'No description'}; weighted score ${m.valid?m.totals[i].toFixed(2)+'/5':'withheld; inputs invalid'}`),`Criteria: ${b.criteria.map(c=>`${c.name} (${c.weight}%)`).join('; ')}\nScores (option order): ${b.scores.map(r=>r.join(', ')).join(' / ')}\nFormula: Σ(score × weight / 100). Team judgments, not objective probabilities.`,...m.errors,...sensitivity(b).map(s=>`Sensitivity: ${s.criterion} weight → ${s.weight}%, other weights scaled proportionally. Leader(s): ${s.leaders.map(i=>b.options[i].name).join(', ')}${s.changed?' — changes the ranking':''}.`),'### Evidence',...b.claims.map((x,i)=>`${i+1}. ${x.claim||'Missing claim'}\nSource: ${x.source||'Missing'} · ${x.date||'No date'} · ${x.locator||'No page/slide'}\n${safeUrl(x.url)||'No valid HTTP/HTTPS source link — treat as assumption.'}`),`Critical assumption: ${b.assumption||'Not entered'}\nEconomics: ${b.economics||'Not entered'}\nStrongest objection: ${b.objection||'Not entered'}\nResponse: ${b.response||'Not entered'}\nImplementation:\n${b.implementation||'Not entered'}`,'## 2. Storyline',...b.slides.map((s,i)=>`### ${i+1}. ${s.headline} (${s.seconds}s · ${s.essential?'essential':'optional'})\n${s.points||'Speaking points missing'}${i===5?'\nLinked assumption: '+(b.assumption||'Not entered'):''}`),`Target: ${b.pitchMinutes} minutes. Allocated: ${plan(b).total} seconds. ${plan(b).errors.join(' ')}`,b.storyFingerprint&&b.storyFingerprint!==decisionFingerprint(b)?'Decision changed since the outline was generated. Review the storyline for consistency.':'','## 3. Judge Q&A',...questions(b).map(q=>`### ${q.question}\nAnswer: ${b.answers[q.id]?.text||'Not prepared'}\nStatus: ${answerPrepared(b,q)?'Marked prepared by team':'Needs work'}`),b.lastRehearsal?`## Last rehearsal\nTotal: ${clock(b.lastRehearsal.seconds)}\n${b.lastRehearsal.splits.map(s=>`Slide ${s.slide+1}: ${clock(s.seconds)}`).join('\n')}`:'','## Preparation gaps',...check.filter(x=>!x.done).map(x=>'- '+x.label),'\nCreated with Case Room. Content and scores are team judgments. Follow your competition’s rules on tools, outside assistance, and required deliverables.'].filter(Boolean).join('\n\n');}
